45	  /**
46	   * Query entries that are due for republishing, inner-joining ipns_records.
47	   *
48	   * D-02 / TEE-03: only schedule rows with a matching ipns_records row that is
49	   * NOT tombstoned AND has an encrypted IPNS key are returned. A tombstoned name
50	   * never enters the batch at this layer (defense layer 1).
51	   *
52	   * Returns an array of { schedule, record } pairs for each due entry.
53	   */
54	  async getDueEntries(): Promise<DueEntryPair[]> {
55	    // Step 1: due schedules via the find-options API (property names; robust
56	    // take-pagination — the query-builder + raw-column + take path trips a TypeORM
57	    // metadata error). LessThanOrEqual here selects rows due by time; it is NOT the
58	    // sequence write-back (that remains an equality CAS in renewIpnsRecordEol).
59	    const schedules = await this.scheduleRepository.find({
60	      where: {
61	        status: In(['active', 'retrying']),
62	        nextRepublishAt: LessThanOrEqual(new Date()),
63	      },
64	      order: { nextRepublishAt: 'ASC' },
65	      take: 2000,
66	    });
67	
68	    if (schedules.length === 0) return [];
69	
70	    // Step 2: fetch the matching ipns_records with the tombstone + key filter
71	    // (D-02 / TEE-03). A tombstoned or key-less record is excluded here, so its
72	    // schedule drops out of the paired result below — a tombstoned name never
73	    // enters the batch (defense layer 1; the renewal CAS is defense layer 2).
74	    const ipnsNames = schedules.map((s) => s.ipnsName);
75	    const records = await this.ipnsRecordRepository.find({
76	      where: {
77	        ipnsName: In(ipnsNames),
78	        tombstonedAt: IsNull(),
79	        encryptedIpnsPrivateKey: Not(IsNull()),
80	      },
81	    });
82	
83	    const recordMap = new Map(records.map((r) => [r.ipnsName, r]));
84	
85	    return schedules
86	      .map((schedule) => {
87	        const record = recordMap.get(schedule.ipnsName);
88	        if (!record) return null; // race: tombstoned or key removed between the two queries
89	        return { schedule, record };
90	      })
91	      .filter((p): p is DueEntryPair => p !== null);
92	  }
93	
94	  /**
95	   * Main orchestration: process all due republish entries.
96	   * Batches entries, sends to TEE for signing, publishes signed records.
97	   */
98	  async processRepublishBatch(): Promise<{
99	    processed: number;
100	    succeeded: number;
101	    failed: number;
102	  }> {
103	    const duePairs = await this.getDueEntries();
104	
105	    if (duePairs.length === 0) {
106	      this.logger.debug('No entries due for republishing');
107	      return { processed: 0, succeeded: 0, failed: 0 };
108	    }
109	
110	    this.logger.log(`Processing ${duePairs.length} due republish entries`);
111	
112	    // Soft capacity warning for large vaults with many per-file IPNS records
113	    if (duePairs.length > 1000) {
114	      this.logger.warn(
115	        `High IPNS record count: ${duePairs.length} entries due for republishing - approaching capacity limits`
116	      );
117	    }
118	
119	    let totalSucceeded = 0;
120	    let totalFailed = 0;
121	
122	    // Split into batches of BATCH_SIZE
123	    for (let i = 0; i < duePairs.length; i += BATCH_SIZE) {
124	      const batch = duePairs.slice(i, i + BATCH_SIZE);
125	
126	      // Build RepublishEntry payloads from the paired ipns_records row.
127	      // D-02 / TEE-03: ALL signing inputs come from the canonical ipns_records row —
128	      // no schedule snapshot fields, no relay-supplied epoch scalars (removed per D-03).
129	      const teeEntries: RepublishEntry[] = batch.map(({ schedule, record }) => ({
130	        encryptedIpnsKey: record.encryptedIpnsPrivateKey!.toString('base64'),
131	        keyEpoch: record.keyEpoch!,
132	        ipnsName: schedule.ipnsName,
133	        signedRecord: record.signedRecord!.toString('base64'),
134	      }));
135	
136	      let teeResults: RepublishResult[];
137	      try {
138	        teeResults = await this.teeService.republish(teeEntries);
139	      } catch (error) {
140	        // TEE unreachable -- mark entire batch as failed
141	        const message = error instanceof Error ? error.message : String(error);
142	        this.logger.error(`TEE worker unreachable: ${message}`);
143	
144	        for (const { schedule } of batch) {
145	          await this.handleEntryFailure(schedule, `TEE unreachable: ${message}`);
146	        }
147	        totalFailed += batch.length;
148	        continue;

